import { Action, ActionPanel, Color, Icon, List, showHUD, showToast, Toast } from "@raycast/api";
import { exec } from "child_process";
import { readFileSync } from "fs";
import { useEffect, useState } from "react";
import { promisify } from "util";

const execPromise = promisify(exec);
const CTL_BIN = "/opt/homebrew/bin/omniwmctl";
const REPO_PATH = "/Users/paranjay/.mac-setup/.config";

interface WindowItem {
  id: string;
  title: string;
  app: {
    name: string;
    bundleId: string;
  };
  workspace: {
    displayName: string;
  };
}

interface Workspace {
  displayName: string;
  isFocused: boolean;
  isVisible: boolean;
  layout: string;
  rawName: string;
  windowCounts: number;
}

interface Shortcut {
  action: string;
  keys: string;
}

export default function Command() {
  const [windows, setWindows] = useState<WindowItem[]>([]);
  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
  const [shortcuts, setShortcuts] = useState<Shortcut[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  // Fetch all stats
  useEffect(() => {
    async function fetchData() {
      try {
        // Fetch workspaces
        const wsOut = await execPromise(`${CTL_BIN} query workspaces --json`);
        const wsResponse = JSON.parse(wsOut.stdout);
        setWorkspaces(wsResponse?.result?.payload?.workspaces || []);

        // Fetch managed windows
        const winOut = await execPromise(`${CTL_BIN} query windows --json`);
        const winResponse = JSON.parse(winOut.stdout);
        setWindows(winResponse?.result?.payload?.windows || []);
      } catch (err) {
        // Fail silently
      }

      try {
        // Parse workflow guide for shortcuts list
        const content = readFileSync("/Users/paranjay/.config/omniwm/WORKFLOW.md", "utf-8");
        const lines = content.split("\n");
        const list: Shortcut[] = [];
        for (const line of lines) {
          if (line.startsWith("- **")) {
            const match = line.match(/-\s+\*\*(.*?):\*\*\s+`(.*?)`/);
            if (match && match[1] && match[2]) {
              list.push({ action: match[1].trim(), keys: match[2].trim() });
            }
          }
        }
        setShortcuts(list);
      } catch (err) {
        setShortcuts([
          { action: "Switch Workspace", keys: "rcmd + [1-9]" },
          { action: "Move Window to Workspace", keys: "rcmd + Shift + [1-9]" },
          { action: "Focus Window (WASD)", keys: "ropt + WASD" },
          { action: "Move Window (WASD)", keys: "ropt + Shift + WASD" }
        ]);
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  // Execution Helper
  async function runOmniCommand(cmd: string, successMsg: string) {
    try {
      await execPromise(`${CTL_BIN} ${cmd}`);
      await showHUD(successMsg);
    } catch (error: any) {
      await showToast({
        style: Toast.Style.Failure,
        title: "Command failed",
        message: error.message,
      });
    }
  }

  // Backup configs
  async function backupConfigs() {
    const toast = await showToast({ style: Toast.Style.Animated, title: "Backing up configs..." });
    try {
      await execPromise(`git -C ${REPO_PATH} add omniwm/settings.toml omniwm/WORKFLOW.md karabiner/karabiner.json`);
      const commitMsg = `backup: raycast auto-sync on ${new Date().toLocaleString()}`;
      await execPromise(`git -C ${REPO_PATH} commit -m "${commitMsg}"`);
      await execPromise(`git -C ${REPO_PATH} push origin main`);
      toast.style = Toast.Style.Success;
      toast.title = "Synced successfully to GitHub!";
    } catch (error: any) {
      if (error.stdout && error.stdout.includes("nothing to commit")) {
        toast.style = Toast.Style.Success;
        toast.title = "Configs are already up to date!";
      } else {
        toast.style = Toast.Style.Failure;
        toast.title = "Failed to sync configs";
        toast.message = error.message;
      }
    }
  }

  // Restore configs
  async function restoreConfigs() {
    const toast = await showToast({ style: Toast.Style.Animated, title: "Restoring configs..." });
    try {
      await execPromise(`git -C ${REPO_PATH} pull origin main`);
      await execPromise("killall OmniWM && sleep 1 && open -a OmniWM");
      toast.style = Toast.Style.Success;
      toast.title = "Restored and OmniWM reloaded!";
    } catch (error: any) {
      toast.style = Toast.Style.Failure;
      toast.title = "Failed to restore configs";
      toast.message = error.message;
    }
  }

  // Generate Workspace Bar Preview String
  // e.g. " [1*]  2.  3.  4.  5.  [6*]  [7*]  8.  9. "
  const getWorkspaceBarPreview = () => {
    return workspaces
      .map((ws) => {
        const layoutChar = ws.layout === "niri" ? "◈" : "⊞";
        const hasWindows = ws.windowCounts > 0 ? "•" : "";
        const formatted = `${ws.displayName}${layoutChar}${hasWindows}`;
        return ws.isFocused || ws.isVisible ? `[ ${formatted} ]` : ` ${formatted} `;
      })
      .join(" | ");
  };

  return (
    <List isLoading={loading} searchBarPlaceholder="Search windows, workspaces, actions, or shortcuts...">
      {/* Workspace Bar Live Preview Row */}
      <List.Section title={`Workspace Bar Live Preview: ${getWorkspaceBarPreview()}`}>
        {workspaces.map((ws) => {
          // List apps on this workspace
          const wsWindows = windows.filter((w) => w.workspace?.displayName === ws.displayName);
          const appNames = Array.from(new Set(wsWindows.map((w) => w.app?.name))).join(", ") || "No windows";
          const layoutChar = ws.layout === "niri" ? "Niri ◈" : "Dwindle ⊞";

          return (
            <List.Item
              key={ws.rawName}
              title={`Workspace ${ws.displayName}`}
              subtitle={appNames}
              accessoryTitle={layoutChar}
              icon={{
                source: ws.isFocused || ws.isVisible ? Icon.CircleProgress100 : Icon.Circle,
                tintColor: ws.isFocused || ws.isVisible ? Color.Blue : Color.Purple
              }}
              actions={
                <ActionPanel>
                  <Action title="Switch to Workspace" onAction={() => runOmniCommand(`command switch-workspace ${ws.rawName}`, `Switched to WS ${ws.displayName}`)} />
                  <Action title="Set Layout: Niri" onAction={() => runOmniCommand(`command set-workspace-layout ${ws.rawName} niri`, "Set WS to Niri")} />
                  <Action title="Set Layout: Dwindle" onAction={() => runOmniCommand(`command set-workspace-layout ${ws.rawName} dwindle`, "Set WS to Dwindle")} />
                </ActionPanel>
              }
            />
          );
        })}
      </List.Section>

      {/* 2. Managed Windows Section */}
      <List.Section title="Managed Windows">
        {windows.map((win) => (
          <List.Item
            key={win.id}
            title={win.app?.name || "Unknown App"}
            subtitle={win.title || "Untitled Window"}
            accessoryTitle={`WS ${win.workspace?.displayName}`}
            icon={{ source: Icon.Window, tintColor: Color.Orange }}
            actions={
              <ActionPanel>
                <Action title="Focus Window" onAction={() => runOmniCommand(`window focus ${win.id}`, "Focused window")} />
                <Action title="Toggle Float State" onAction={() => runOmniCommand("command toggle-focused-window-floating", "Toggled float state")} />
                <Action title="Toggle Fullscreen" onAction={() => runOmniCommand("command toggle-fullscreen", "Toggled fullscreen")} />
              </ActionPanel>
            }
          />
        ))}
      </List.Section>

      {/* 3. Common Layout Actions */}
      <List.Section title="Layout Controls">
        <List.Item
          title="Balance Sizing"
          subtitle="Even out window sizing across layout"
          icon={{ source: Icon.AppWindow, tintColor: Color.Green }}
          actions={<ActionPanel><Action title="Run Command" onAction={() => runOmniCommand("command balance-sizes", "Balanced layout sizes")} /></ActionPanel>}
        />
        <List.Item
          title="Toggle Full Width"
          subtitle="Toggle container primary span"
          icon={{ source: Icon.Maximize, tintColor: Color.Yellow }}
          actions={<ActionPanel><Action title="Run Command" onAction={() => runOmniCommand("command toggle-container-full-primary-span", "Toggled full width")} /></ActionPanel>}
        />
        <List.Item
          title="Toggle Workspace Bar"
          subtitle="Toggle the visibility of the menu bar panel"
          icon={{ source: Icon.Sidebar, tintColor: Color.Purple }}
          actions={<ActionPanel><Action title="Run Command" onAction={() => runOmniCommand("command toggle-workspace-bar", "Toggled workspace bar")} /></ActionPanel>}
        />
        <List.Item
          title="Toggle Layout Type"
          subtitle="Toggle workspace layout (Niri ↔ Dwindle)"
          icon={{ source: Icon.Repeat, tintColor: Color.Red }}
          actions={<ActionPanel><Action title="Run Command" onAction={() => runOmniCommand("command toggle-workspace-layout", "Toggled layout")} /></ActionPanel>}
        />
      </List.Section>

      {/* 4. VCS Configuration Sync */}
      <List.Section title="Dotfiles VCS Control">
        <List.Item
          title="Sync/Backup Configs to GitHub"
          subtitle="Git add, commit, and push omniwm/karabiner configs"
          icon={{ source: Icon.Cloud, tintColor: Color.Blue }}
          actions={<ActionPanel><Action title="Backup to GitHub" onAction={backupConfigs} /></ActionPanel>}
        />
        <List.Item
          title="Restore Configs from GitHub"
          subtitle="Git pull latest configurations and restart OmniWM"
          icon={{ source: Icon.Download, tintColor: Color.Green }}
          actions={<ActionPanel><Action title="Restore from GitHub" onAction={restoreConfigs} /></ActionPanel>}
        />
      </List.Section>

      {/* 5. Shortcuts Visualization */}
      <List.Section title="Shortcuts Guide">
        {shortcuts.map((sc, index) => (
          <List.Item
            key={index}
            title={sc.action}
            subtitle={sc.keys}
            icon={{ source: Icon.Keyboard, tintColor: Color.Purple }}
            actions={
              <ActionPanel>
                <Action.CopyToClipboard title="Copy Shortcut" content={sc.keys} />
              </ActionPanel>
            }
          />
        ))}
      </List.Section>
    </List>
  );
}
